```cpp
#include <cerrno>
#include <iostream>
#include <stdexcept>

#include <sys/socket.h>
#include <sys/types.h>
#include <sys/un.h>
#include <unistd.h>

using namespace std;

int main(int argc, char *argv[]) {
        int r;
        int sv[2];
        char c;

        r = ::socketpair(AF_UNIX, SOCK_STREAM, 0, sv);
        if (-1 == r) {
                throw system_error(errno, system_category(), "socketpair(2)");
        }

        r = ::write(sv[0], "x", 1);
        if (-1 == r) {
                throw system_error(errno, system_category(), "write(2)");
        }

        ::sockaddr_un sa = {};
        ::socklen_t len = sizeof(sa);
        r = recvfrom(sv[1], &c, 1, 0, (::sockaddr *) &sa, &len);
        if (-1 == r) {
                throw system_error(errno, system_category(), "recvfrom(2)");
        }

        cout << "r: " << r << " len: " << len << endl;

        return 0;
}
```
```bash
$ ./foo 
r: 1 len: 0
```
So on Linux, connected PF_UNIX is not supported in terms of addressing, and they truncate the length to 0. No error is thrown. Probably safe to do the same thing here.

POSIX does not say to *not* touch addrlen, but you were right in saying that it's a bit of a questionable area.

